parameters.jsCode:
// Validate HITL output
const input = $input.first().json;
let output = input.output || input.response || input.text || input.content || '';

let parsed;
try {
  const mdMatch = output.match(/```json\n([\s\S]*?)\n```/) || output.match(/```\n([\s\S]*?)\n```/);
  if (mdMatch && mdMatch[1]) parsed = JSON.parse(mdMatch[1].trim());
  else {
    const jsonMatch = output.match(/\{[\s\S]*\}/);
    if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
    else parsed = JSON.parse(output);
  }
} catch (e) {
  return [{
    json: {
      valid: false,
      error: 'Parse error: ' + e.message,
      raw_output: output.substring(0, 3000),
      action: 'edit',
      updated_content: input.current_content || '',
      changes_made: [],
      sections_modified: [],
      notes: 'Failed to parse edit output'
    }
  }];
}

if (!parsed.action) parsed.action = 'edit';
if (!parsed.updated_content) parsed.updated_content = input.current_content || '';
if (!Array.isArray(parsed.changes_made)) parsed.changes_made = [];
if (!Array.isArray(parsed.sections_modified)) parsed.sections_modified = [];
if (!parsed.notes) parsed.notes = '';

return [{ json: { valid: true, ...parsed } }];
